(function(){
'use strict';
const SB=()=>window.barokahSupabase,BUCKET='bukti-transfer',MAX=3,MAX_SIZE=8*1024*1024,$=id=>document.getElementById(id);
const factor=u=>{const k=String(u||'').trim().toLowerCase();return k==='papan'?30:k==='ikat'?180:1};
const ext=f=>f.type==='image/jpeg'?'jpg':f.type==='image/png'?'png':'webp';
const uid=()=>crypto?.randomUUID?crypto.randomUUID():String(Date.now())+'-'+Math.random().toString(36).slice(2);
const num=v=>typeof parseInputNumber==='function'?parseInputNumber(v):Number(String(v||'').replace(/[^0-9.-]/g,''));
const toast=m=>typeof window.toast==='function'?window.toast(m):alert(m);
function style(){if($('bundle71Style'))return;const s=document.createElement('style');s.id='bundle71Style';s.textContent='.bundle71-open{position:fixed;right:22px;bottom:22px;z-index:99990;border:0;border-radius:16px;padding:13px 17px;background:#123d2a;color:#fff;font-weight:800;box-shadow:0 12px 35px rgba(0,0,0,.2);cursor:pointer}.bundle71-bg{position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:99999}.bundle71-box{position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);width:min(760px,calc(100vw - 24px));max-height:92vh;overflow:auto;background:#fff;border-radius:22px;padding:22px;box-shadow:0 25px 90px rgba(0,0,0,.3);z-index:100000}.bundle71-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.bundle71-box label{display:block;font-size:12px;font-weight:800;color:#47534b}.bundle71-box input,.bundle71-box select{width:100%;margin-top:5px;padding:11px;border:1px solid #d7dfd9;border-radius:10px;background:#fff}.bundle71-section{margin-top:16px;padding:15px;border:1px solid #e0e7e2;border-radius:15px}.bundle71-actions{display:flex;gap:10px;justify-content:flex-end;margin-top:18px}.bundle71-actions button{border:0;border-radius:10px;padding:11px 16px;font-weight:800;cursor:pointer}.bundle71-save{background:#123d2a;color:#fff}.bundle71-cancel{background:#edf1ee}.bundle71-help{font-size:11px;color:#69756e;margin-top:6px}@media(max-width:600px){.bundle71-grid{grid-template-columns:1fr}.bundle71-open{right:12px;bottom:12px}}';document.head.appendChild(s)}
function input(id){return $(id)?.value||''}
function open(){style();$('bundle71Modal')?.remove();const m=document.createElement('div');m.id='bundle71Modal';m.innerHTML='<div class="bundle71-bg"></div><div class="bundle71-box"><div style="display:flex;justify-content:space-between;gap:12px;align-items:center"><div><h2 style="margin:0">📦 Simpan Paket Bisnis</h2><div class="bundle71-help">Transaksi, stok gudang, dan bukti transfer disimpan sebagai satu paket dengan satu ID transaksi.</div></div><button type="button" id="bundle71X" style="border:0;background:#edf1ee;border-radius:10px;width:40px;height:40px;font-size:20px">×</button></div><div class="bundle71-section"><b>1. Transaksi</b><div class="bundle71-grid" style="margin-top:12px"><label>Jenis<select id="bundle71Type"><option value="income">Uang Masuk</option><option value="expense">Uang Keluar</option></select></label><label>Tanggal<input id="bundle71Date" type="date"></label><label>Keterangan<input id="bundle71Note" placeholder="Contoh: Penjualan telur"></label><label>Satuan<input id="bundle71Unit" placeholder="Ikat / Butir / Papan"></label><label>Harga<input id="bundle71Price" inputmode="decimal" placeholder="0"></label><label>Jumlah<input id="bundle71Qty" inputmode="decimal" placeholder="0"></label></div></div><div class="bundle71-section"><b>2. Pergerakan Stok (opsional)</b><div class="bundle71-grid" style="margin-top:12px"><label>Jenis<select id="bundle71StockType"><option value="">Tidak ada</option><option value="Masuk">Masuk</option><option value="Keluar">Keluar</option><option value="Retak">Retak</option><option value="Tidak Layak">Tidak Layak</option></select></label><label>Satuan<input id="bundle71StockUnit" placeholder="Ikat / Butir / Papan"></label><label>Jumlah<input id="bundle71StockQty" inputmode="decimal" placeholder="0"></label><label>Keterangan<input id="bundle71StockNote" placeholder="Keterangan stok"></label></div></div><div class="bundle71-section"><b>3. Bukti Transfer (opsional, maksimal 3)</b><input id="bundle71Proofs" type="file" accept="image/jpeg,image/png,image/webp" multiple><div class="bundle71-help">Bukti diunggah memakai ID paket yang sama. Metadata bukti masuk ke transaksi yang sama secara atomik.</div></div><div class="bundle71-actions"><button type="button" class="bundle71-cancel" id="bundle71Cancel">Batal</button><button type="button" class="bundle71-save" id="bundle71Save">💾 Simpan Paket</button></div></div>';document.body.appendChild(m);const close=()=>m.remove();$('bundle71X').onclick=close;$('bundle71Cancel').onclick=close;$('bundle71Date').value=new Date().toISOString().slice(0,10);$('bundle71Save').onclick=()=>save(m)}
async function uploadFiles(user,tx,files){const out=[];for(const f of files){if(!['image/jpeg','image/png','image/webp'].includes(f.type))throw Error('Bukti hanya JPG, PNG atau WebP.');if(f.size>MAX_SIZE)throw Error('Ukuran bukti maksimal 8 MB/file.');const path=user.id+'/'+tx+'/'+uid()+'.'+ext(f);const up=await SB().storage.from(BUCKET).upload(path,f,{contentType:f.type,upsert:false});if(up.error)throw up.error;out.push({storage_path:path,file_name:f.name,mime_type:f.type,file_size:f.size})}return out}
async function save(modal){const sb=SB();if(!sb){alert('Koneksi Supabase belum siap.');return}const auth=await sb.auth.getUser(),u=auth.data?.user;if(!u){alert('Sesi login tidak aktif.');return}const type=input('bundle71Type'),note=input('bundle71Note').trim(),unit=input('bundle71Unit').trim(),price=num(input('bundle71Price')),qty=num(input('bundle71Qty')),date=input('bundle71Date'),st=input('bundle71StockType'),su=input('bundle71StockUnit').trim(),sq=num(input('bundle71StockQty')),sn=input('bundle71StockNote').trim(),files=[...($('bundle71Proofs')?.files||[])];if(!note||!unit||!date||!Number.isFinite(price)||price<0||!Number.isFinite(qty)||qty<=0){alert('Lengkapi transaksi: keterangan, tanggal, satuan, harga, dan jumlah.');return}if(files.length>MAX){alert('Maksimal 3 bukti transfer.');return}if(st&&(!Number.isFinite(sq)||sq<=0)){alert('Jumlah stok tidak valid.');return}if(st&&!su){alert('Satuan stok wajib diisi.');return}let uploaded=[];try{$('bundle71Save').disabled=true;$('bundle71Save').textContent='Menyimpan paket...';const tx=uid();const stock=st?{movement_type:st,qty:sq,unit:su,delta_butir:(st==='Masuk'?1:-1)*sq*factor(su),note:sn}:null;const proofs=files.length?await uploadFiles(u,tx,files):[];uploaded=proofs.map(x=>x.storage_path);const r=await sb.rpc('save_business_bundle',{p_type:type,p_note:note,p_price:price,p_unit:unit,p_qty:qty,p_total:Number((price*qty).toFixed(3)),p_transaction_date:date,p_stock:stock,p_proofs:proofs,p_transaction_id:tx});if(r.error)throw r.error;modal.remove();if(typeof window.barokahCloudSync==='function')await window.barokahCloudSync();if(window.barokahBuktiTransfer?.refresh)await window.barokahBuktiTransfer.refresh();toast('Paket bisnis tersimpan lengkap: transaksi + stok + bukti transfer.');}catch(e){for(const p of uploaded)await sb.storage.from(BUCKET).remove([p]).catch(()=>{});console.error(e);alert('Gagal menyimpan paket: '+(e.message||e));$('bundle71Save').disabled=false;$('bundle71Save').textContent='💾 Simpan Paket'}}
function install(){style();if($('bundle71Open'))return;const b=document.createElement('button');b.id='bundle71Open';b.className='bundle71-open';b.type='button';b.textContent='📦 Simpan Paket Bisnis';b.onclick=open;document.body.appendChild(b)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(install,1600));else setTimeout(install,1600);
window.barokahBusinessBundle={open,save};
})();
